const e="Nous ne sommes pas nés pour régner. Nous sommes nés pour choisir ce que nous ferons de notre monde.",s="Dicton ancestral Valm",t=["Peuple & Lignée","Origine Humaine","Codex #PEU-001"],n=[1,2,15],i="Vieux Monde, Nordheim, Nouveau Monde, Tangfall, Elogos",o="Adaptabilité, Diversité culturelle",r="160cm - 190cm",a="80",l="« Ceux des terres habitées »",u="Valm_icone.jpeg",c="Très Représenté",d=[{title:"Présentation",type:"text",content:"Les Valm sont le nom ancestral donné à l'ensemble de l'espèce humaine d'Asun. Le terme « humain » est aujourd'hui le plus couramment utilisé, mais Valm demeure le nom historique de leur peuple. Les Valm sont présents sur une grande partie d'Asun et ont développé des civilisations extrêmement différentes les unes des autres."},{title:"Origines",type:"text",content:"L'origine exacte des Valm appartient aux Histoires Perdues. Les premières traces connues de leur civilisation apparaissent bien après l'éveil des Dieux. Les traditions de Lorus affirment que les humains ont reçu leur destinée d'Edes, tandis que d'autres cultures racontent des origines très différentes."},{title:"L'Âge des Dragons",type:"text",content:"Durant l'Âge des Dragons, les Valm vivaient sous la domination draconique. Lorsque plusieurs communautés humaines décidèrent finalement de se soulever, elles s'unirent avec l'aide d'Edes pour remporter la guerre et fonder Lorus."},{title:"Les Valm et les autres peuples",type:"politique_list_long",content:[{headline:"Tendu",title:"Les Kovraks",content:"Les relations avec les Kovraks sont marquées par des siècles de conflit entre Lorus et Koven suite à l'oppression subie par les Kovraks.",color:"#FF7A5C"},{headline:"Complexe",title:"Les Elfes",content:"Les relations varient selon les régions ; le commerce existe mais des méfiances persistent vis-à-vis des ambitions expansionnistes valm.",color:"#C29B38"},{headline:"Hostile (Historique)",title:"Les Dragons & Dra’Zuun",content:"Après la chute des Dragons, les Valm ont entretenu une forte suspicion envers leurs descendants et héritiers.",color:"#FF7A5C"}]},{title:"Aujourd'hui",type:"text",content:"Les Valm constituent l'un des peuples les plus nombreux et influents d'Asun. Ils contrôlent de grandes puissances politiques (Lorus, Cytanie) et continuent d'avoir un impact majeur sur le monde."}],m={citation:e,citation_author:s,tags:t,link_articles:n,class:"Humaine",repart:i,trait:o,height:r,age:a,surname:l,image:u,statut:c,sections:d};export{a as age,e as citation,s as citation_author,m as default,r as height,u as image,n as link_articles,i as repart,d as sections,c as statut,l as surname,t as tags,o as trait};
